   const tbl=h('div',{className:'k4Row'}); st.melds.forEach((m,mi)=>{ const e=h('div',{className:'k4Meld'+(st.sel.size===1&&st.phase==='play'&&valid(m.cards.concat([st.hands[0][[...st.sel][0]]]))?' can':''),title:NM[m.o]+'’s meld'}); m.cards.forEach(c=>e.appendChild(cardEl(c,Math.round(w*.6)))); e.addEventListener('click',()=>{ if(st.turn||st.phase!=='play'||st.sel.size!==1) return; const c=st.hands[0][[...st.sel][0]]; if(valid(m.cards.concat([c]))){ m.cards.push(c); m.cards.sort((a,b)=>a.r-b.r); st.pts[0]+=r5pts(c); st.hands[0].splice(st.hands[0].indexOf(c),1); st.sel=new Set(); st.msg='Laid off '+cn(c)+'.'; if(!st.hands[0].length) return endDeal(); render(); } }); tbl.appendChild(e); }); if(!st.melds.length) tbl.appendChild(h('div',{className:'k4Msg'},'No melds yet')); root.appendChild(tbl);
   const mid=h('div',{className:'k4Row'}); const sk=h('div',{className:'k4Pile'}); sk.appendChild(cardEl({r:2,s:0},Math.round(w*.9),true)); sk.appendChild(h('span',null,'Stock '+st.stock.length)); sk.addEventListener('click',()=>{ if(!st.turn&&st.phase==='draw'&&!st.over&&st.stock.length){ st.hands[0].push(st.stock.pop()); st.phase='play'; st.msg='Meld, lay off, then discard.'; render(); } }); mid.appendChild(sk);
   const dp=h('div',{className:'k4Row',style:'gap:0'}); st.disc.forEach((c,k)=>{ const e=cardEl(c,Math.round(w*.62)); e.style.marginLeft=k?'-'+Math.round(w*.3)+'px':'0'; e.style.cursor='pointer'; e.addEventListener('click',()=>take(k)); dp.appendChild(e); }); mid.appendChild(dp); root.appendChild(mid);
   root.appendChild(h('div',{className:'k4Msg'},st.msg+' · This deal: you '+(st.pts[0]>=0?'+':'')+st.pts[0]+' · Total '+st.score[0]));
